import fs from 'node:fs'; import path from 'node:path';
const yaml = await import(process.argv[2]); const dir = process.argv[3];
const docs = {}, all = {};
for (const f of fs.readdirSync(dir).filter(f => f.endsWith('.yaml'))) { docs[f] = yaml.load(fs.readFileSync(path.join(dir, f), 'utf8')); for (const l of docs[f].lessons) all[l.key] = l; }
const P = 'paperclip@e8b78cce5bb5:';
const L = (o) => (docs['data-model.yaml'].lessons.push({ decision: { state: 'candidate' }, ...o }));
// --- convergence with gr8r lessons ---
const conv = (k, wh, ev, extra = {}) => { const l = all[k]; l.where.push(...wh); l.score.evidence = ev; Object.assign(l, extra); };
conv('client-random-ids-and-keys', [P+'server/src/services/issues.ts#L10436-L10447', P+'packages/db/src/schema/companies.ts#L7-L22'], 2, {
  notable: 'Fine for one browser, wrong for several writers: two writers (the owner and an agent) both increment seq and produce the same key, and 6 random characters collide at scale. Paperclip shows the fix in practice: uuid primary keys, and the human key (PAP-123) assigned by one atomic UPDATE ... RETURNING on a per-company counter. In D1 the same single statement is atomic, so no lock or Durable Object is needed for key assignment.' });
all['client-random-ids-and-keys'].score.why = 'Core (data-model). a: vision §4 has several writers creating tasks; client-side seq gives duplicate keys; b: no id scheme yet; d: server-assigned keys; e: duplicates go unnoticed until links break. Two sources: gr8r shows the problem, paperclip the server-side counter in use.';
conv('review-and-at-risk-states', [P+'packages/shared/src/constants.ts#L190-L198'], 2);
all['review-and-at-risk-states'].score.why = 'Core (handoff). a: vision §5 has agents finish work for the owner to accept; without a review state an agent marks its own task done; b: no such state; d: an enum the API enforces. gr8r and paperclip both carry a review state (in_review) independently. Template edit only.';
conv('activity-log-from-mutation-door', [P+'server/src/services/activity-log.ts#L230-L242', P+'server/src/routes/goals.ts#L33-L33'], 2, {
  notable: 'The log should be a side effect of the only write path, so it cannot be forgotten. gr8r does this inside applyPatch; paperclip has one central logActivity() writer but every route calls it explicitly, so a new route can forget it. With a schema-generated API the generated mutation handler should write activity automatically — the strongest form of both.' });
all['activity-log-from-mutation-door'].score.why = 'Core (storage-sync). a: vision §4 has owner and agents writing concurrently and today log.md is written by hand; b: no write door exists; c: every mutation; d: generated handler; e: a missing entry is silent. Two independent sources use a central activity writer.';
// --- new paperclip lessons ---
L({ key: 'shared-validators-one-vocabulary', domains: ['data-model', 'agent-bridge'], layer: 'content',
  what: 'Paperclip keeps statuses, priorities and request bodies as zod schemas and `as const` arrays in packages/shared; server routes, the MCP tools (which .merge() the shared schemas), the CLI and a hand-built OpenAPI document all import them. Tables are separate Drizzle definitions in packages/db, and the 44 MCP tools are a hand-written list.',
  notable: 'Half of the "one schema" idea: one validation vocabulary prevents API/MCP drift ("so the public API cannot drift"), but tables, the tool list and the agent-facing docs are still written by hand, and TASKS-mcp.md already names operations (list_my_issues…) that do not exist as tools. For fgOPC: make one entity registry the source and generate the D1 DDL, the REST routes, the MCP tool list and the UI types from it, instead of only sharing validators.',
  where: [P+'packages/shared/src/constants.ts#L190-L213', P+'packages/mcp-server/src/tools.ts#L133-L148', P+'packages/mcp-server/src/index.ts#L15-L17', P+'server/src/routes/openapi.ts#L801-L804'],
  contrast: 'extends', host: 'docs/vision.md', keywords: ['zod', 'shared validators', 'openapi', 'mcp tools', 'drift', 'schema-first'],
  score: { relevance: 3, facts: ['a','b','c','d','e'], evidence: 1, effort: 2, why: 'Core (data-model). a: the goal requires one schema for DB, API, MCP and UI, and hand-written tool lists drift; b: no schema yet; c: every entity × every surface; d: codegen + a check that generated files are fresh; e: paperclip doc TASKS-mcp.md already drifted silently from the real tools. One source.' } });
L({ key: 'atomic-checkout-single-update', domains: ['storage-sync', 'handoff'], layer: 'content',
  what: 'An agent claims an issue with POST /checkout, implemented as one conditional UPDATE: set assignee, run id, status in_progress WHERE status IN expectedStatuses AND (no assignee OR same run) AND no other execution run; zero rows updated returns 409, and the skill tells agents "Never retry a 409". Release clears the run ids.',
  notable: 'No locks, no queue, no long-running process: the database row is the lock. SQLite/D1 executes a single UPDATE ... WHERE atomically, so this ports directly to a Worker and stops two agents (or two runs of one agent) from working the same task. Trade-off: a crashed run keeps the lock until a sweep clears stale run ids (paperclip reaps after 5 minutes; on Cloudflare a Cron Trigger).',
  where: [P+'server/src/services/issues.ts#L12003-L12027', P+'skills/paperclip/SKILL.md#L123-L131'],
