  score: { relevance: 3, facts: ['a', 'b', 'e'], evidence: 2, effort: 3, why: 'Core (agent-bridge). a: the spike ran OpenClaw through a hidden, capability-less adapter that needed a protocol patch; b: the host has not decided which runtime owns agents; e: the mismatch only showed up in practice (spike). Observed in practice.' },
  decision: { state: 'candidate' } });
