import { client } from "@kaneo/libs";
import type { InferRequestType } from "hono/client";
import { HttpError } from "@/lib/http-error";

export type UpdateCommentRequest = InferRequestType<
  (typeof client)["activity"]["comment"]["$put"]
>["json"];

