#!/usr/bin/env python3
# /// script
# requires-python = ">=3.10"
# dependencies = ["pyyaml>=6"]
# ///
"""opc: lint, pack and deploy an OPC package to Multica.

An OPC package is an Agent Companies v1 package (COMPANY.md, teams/, agents/,
projects/, tasks/, skills/) plus the fgopc extension: workflows/<slug>/WORKFLOW.md
and .fgopc.yaml. See ../spec/package-format.md.

    opc.py lint   <package>
    opc.py pack   <package> [-o out.tar.gz]
    opc.py plan   <package>                 # what deploy would change, no writes
    opc.py deploy <package> [--activate-routines]

Deploy is idempotent: entities are matched by slug through a state file
(<package>/.opc/multica-<workspace>.json), falling back to name. Secret values
come from environment variables named in .fgopc.yaml and are never printed.

Environment: MULTICA_API (default http://127.0.0.1:8310), MULTICA_TOKEN_FILE
(default $MULTICA_HOME/.pat, MULTICA_HOME default ~/multica-spike).
"""
import argparse, hashlib, io, json, os, re, sys, tarfile, urllib.error, urllib.request
from pathlib import Path

import yaml

SCHEMA = "agentcompanies/v1"
EXT_SCHEMA = "fgopc/v1"
BUILTIN_STATUSES = {"backlog", "todo", "in_progress", "in_review", "done", "blocked", "cancelled"}
CATEGORIES = {"unstarted", "started", "done", "closed"}
SECRET_PATTERNS = [
    re.compile(r"sk-[A-Za-z0-9_-]{20,}"), re.compile(r"ghp_[A-Za-z0-9]{30,}"),
    re.compile(r"mul_[A-Za-z0-9]{20,}"), re.compile(r"AKIA[0-9A-Z]{16}"),
    re.compile(r"-----BEGIN [A-Z ]*PRIVATE KEY-----"), re.compile(r"xox[bap]-[A-Za-z0-9-]{10,}"),
]
TEXT_SUFFIXES = {".md", ".txt", ".yaml", ".yml", ".json", ".py", ".sh", ".js", ".ts", ".csv", ".html"}


# ---------------------------------------------------------------- package model

def read_doc(path):
    """Split a markdown file into (frontmatter dict, body)."""
    text = path.read_text(encoding="utf-8")
    if text.startswith("---\n"):
        end = text.find("\n---", 4)
        if end != -1:
            meta = yaml.safe_load(text[4:end]) or {}
            return meta, text[end + 4:].lstrip("\n"), text
    return {}, text, text


def ref_slug(ref):
    """'agents/lan/AGENTS.md', '../lan/AGENTS.md' or 'lan' -> 'lan'."""
    if not ref:
        return None
    p = Path(str(ref))
    return p.parent.name if p.suffix == ".md" else p.name


class Package:
    def __init__(self, root):
        self.root = Path(root).resolve()
        self.errors, self.warnings = [], []
        if not (self.root / "COMPANY.md").exists():
            raise SystemExit(f"{self.root}: no COMPANY.md, not a company package")
        self.company, self.company_body, _ = read_doc(self.root / "COMPANY.md")
        self.ext = yaml.safe_load((self.root / ".fgopc.yaml").read_text()) if (self.root / ".fgopc.yaml").exists() else {}
        self.agents = self._load("agents/*/AGENTS.md")
        self.teams = self._load("teams/*/TEAM.md")
        self.projects = self._load("projects/*/PROJECT.md")
        self.tasks = self._load("tasks/*/TASK.md")
        for slug, t in self._load("projects/*/tasks/*/TASK.md").items():
            t["meta"].setdefault("project", t["path"].parent.parent.parent.name)
            self.tasks[slug] = t
        self.workflows = self._load("workflows/*/WORKFLOW.md")
        self.skills = {}
        for path in sorted(self.root.glob("skills/*/SKILL.md")):
            meta, body, raw = read_doc(path)
            self.skills[path.parent.name] = {"meta": meta, "body": body, "raw": raw, "path": path}

    def _load(self, pattern):
        out = {}
        for path in sorted(self.root.glob(pattern)):
            meta, body, _ = read_doc(path)
            out[meta.get("slug") or path.parent.name] = {"meta": meta, "body": body, "path": path}
        return out

    @property
    def slug(self):
        return self.company.get("slug")

    def target(self, name):
        return (self.ext.get("targets") or {}).get(name) or {}

    def team_members(self, slug):
        """(manager slug, member agent slugs without the manager)."""
        meta = self.teams[slug]["meta"]
        manager = ref_slug(meta.get("manager"))
        members = [ref_slug(i) for i in meta.get("includes") or [] if "AGENTS.md" in str(i) or ref_slug(i) in self.agents]
        return manager, [m for m in members if m and m != manager]

    def is_squad(self, slug):
        return bool(self.team_members(slug)[1])

    def agent_instructions(self, slug):
        a = self.agents[slug]
        parts = [a["body"].strip()]
        for extra in ("SOUL.md", "RULES.md"):
            f = a["path"].parent / extra
            if f.exists():
                parts.append(f.read_text(encoding="utf-8").strip())
        return "\n\n".join(p for p in parts if p)

    def files(self):
        skip = {".opc", ".git", "__pycache__"}
        return sorted(p for p in self.root.rglob("*") if p.is_file() and not skip & set(p.relative_to(self.root).parts))


# ---------------------------------------------------------------------- lint

def lint(pkg):
    E, W = pkg.errors, pkg.warnings
    c = pkg.company
    for f in ("name", "slug", "description", "schema"):
        if not c.get(f):
            E.append(f"COMPANY.md: missing {f}")
    if c.get("schema") and c["schema"] != SCHEMA:
        E.append(f"COMPANY.md: schema {c['schema']!r}, expected {SCHEMA!r}")
    if pkg.ext and pkg.ext.get("schema") != EXT_SCHEMA:
        E.append(f".fgopc.yaml: schema must be {EXT_SCHEMA!r}")

    for slug, s in pkg.skills.items():
        m = s["meta"]
        if m.get("name") != slug:
            E.append(f"skills/{slug}: SKILL.md name must equal the directory name (Agent Skills)")
        if not m.get("description"):
            E.append(f"skills/{slug}: SKILL.md needs a description")

    for slug, a in pkg.agents.items():
        m = a["meta"]
        if not m.get("name"):
            E.append(f"agents/{slug}: missing name")
        elif len(m["name"]) > 64:
            E.append(f"agents/{slug}: name longer than 64 characters")
        for sk in m.get("skills") or []:
            if sk not in pkg.skills:
                E.append(f"agents/{slug}: skill {sk!r} not found under skills/")
        rt = ref_slug(m.get("reportsTo"))
        if rt and rt not in pkg.agents:
            E.append(f"agents/{slug}: reportsTo {rt!r} is not an agent")
        if not a["body"].strip():
            W.append(f"agents/{slug}: empty instructions body")

    for slug in pkg.teams:
        manager, members = pkg.team_members(slug)
        if manager not in pkg.agents:
            E.append(f"teams/{slug}: manager {manager!r} is not an agent")
        for m in members:
            if m not in pkg.agents:
                E.append(f"teams/{slug}: includes unknown agent {m!r}")

    for slug, p in pkg.projects.items():
        owner = p["meta"].get("owner")
        if owner and owner not in pkg.agents:
            E.append(f"projects/{slug}: owner {owner!r} is not an agent")

    for slug, t in pkg.tasks.items():
        m = t["meta"]
        who = m.get("assignee")
        if who and who not in pkg.agents and who not in pkg.teams:
            E.append(f"tasks/{slug}: assignee {who!r} is not an agent or team")
        if m.get("project") and m["project"] not in pkg.projects:
            E.append(f"tasks/{slug}: project {m['project']!r} not found")
        if m.get("recurring") and not ((pkg.ext.get("routines") or {}).get(slug) or {}).get("triggers"):
            W.append(f"tasks/{slug}: recurring but no triggers in .fgopc.yaml routines; deployed without a schedule")
        if not m.get("recurring"):
            W.append(f"tasks/{slug}: one-time tasks are not deployed (only recurring tasks become autopilots)")

    bound = {}
    for slug, cfg in (pkg.ext.get("projects") or {}).items():
        if slug not in pkg.projects:
            E.append(f".fgopc.yaml projects: {slug!r} has no PROJECT.md")
        wf = (cfg or {}).get("workflow")
        if wf and wf not in pkg.workflows:
            E.append(f".fgopc.yaml projects.{slug}: workflow {wf!r} not found")
        bound[slug] = wf

    for slug, w in pkg.workflows.items():
        m = w["meta"]
        steps = m.get("statuses") or []
        if m.get("kind") != "workflow":
            E.append(f"workflows/{slug}: kind must be 'workflow'")
        if not steps:
            E.append(f"workflows/{slug}: no statuses")
        if len(steps) > 50:
            E.append(f"workflows/{slug}: more than 50 statuses")
        keys = {s.get("key") for s in steps}
        for s in steps:
            k = s.get("key")
            if not k or not re.fullmatch(r"[a-z][a-z0-9_]*", k):
                E.append(f"workflows/{slug}: bad status key {k!r}")
            if k not in BUILTIN_STATUSES:
                if not s.get("name"):
                    E.append(f"workflows/{slug}.{k}: a new status needs a name")
                if s.get("category") not in CATEGORIES:
                    E.append(f"workflows/{slug}.{k}: a new status needs category in {sorted(CATEGORIES)}")
            for edge in ("next", "back"):
                if s.get(edge) and s[edge] not in keys:
                    E.append(f"workflows/{slug}.{k}: {edge} {s[edge]!r} is not a status of this workflow")
            h = s.get("handler") or {}
            if "agent" in h and h["agent"] not in pkg.agents:
                E.append(f"workflows/{slug}.{k}: handler agent {h['agent']!r} not found")
            if "team" in h and h["team"] not in pkg.teams:
                E.append(f"workflows/{slug}.{k}: handler team {h['team']!r} not found")
            if len(s.get("instructions") or "") > 8000:
                E.append(f"workflows/{slug}.{k}: instructions longer than 8000 characters")
        if m.get("rules"):
            W.append(f"workflows/{slug}: Multica does not enforce rules; they are added to step instructions")
        if slug not in bound.values():
            W.append(f"workflows/{slug}: not bound to any project in .fgopc.yaml")

    names = [a["meta"].get("name") for a in pkg.agents.values()]
    if len(names) != len(set(names)):
        E.append("agents: names must be unique (Multica matches by name)")

    for path in pkg.files():
        rel = path.relative_to(pkg.root)
        if path.name in {".env", ".pat", ".jwt"} or path.suffix in {".pem", ".key"}:
            E.append(f"{rel}: forbidden file in a package")
            continue
        if path.suffix in TEXT_SUFFIXES:
            text = path.read_text(encoding="utf-8", errors="replace")
            if any(p.search(text) for p in SECRET_PATTERNS):
                E.append(f"{rel}: looks like it contains a secret")
        elif path.suffix not in {".png", ".jpg", ".jpeg", ".svg", ".gif", ".webp"}:
            W.append(f"{rel}: executable or binary content; review before import")
    return not E


def print_lint(pkg):
    ok = lint(pkg)
    for e in pkg.errors:
        print("error:", e)
    for w in pkg.warnings:
        print("warn: ", w)
    print(f"{pkg.slug}: {len(pkg.agents)} agents, {len(pkg.teams)} teams, {len(pkg.skills)} skills, "
          f"{len(pkg.workflows)} workflows, {len(pkg.projects)} projects, {len(pkg.tasks)} tasks"
          f" -> {'ok' if ok else 'FAILED'}")
    return ok


# ---------------------------------------------------------------------- pack

def pack(pkg, out):
    files = pkg.files()
    lock = {"schema": SCHEMA, "package": pkg.slug, "version": pkg.company.get("version"),
            "files": {str(p.relative_to(pkg.root)): hashlib.sha256(p.read_bytes()).hexdigest() for p in files}}
    lock_bytes = (json.dumps(lock, indent=2, ensure_ascii=False) + "\n").encode()
    (pkg.root / "company-package.lock.json").write_bytes(lock_bytes)
    prefix = f"{pkg.slug}-{pkg.company.get('version', '0.0.0')}"
    out = Path(out or f"{prefix}.tar.gz")
    with tarfile.open(out, "w:gz") as tar:
        for p in files:
            if p.name != "company-package.lock.json":
                tar.add(p, arcname=f"{prefix}/{p.relative_to(pkg.root)}")
        info = tarfile.TarInfo(f"{prefix}/company-package.lock.json")
        info.size = len(lock_bytes)
        tar.addfile(info, io.BytesIO(lock_bytes))
    print(f"wrote {out} ({len(files)} files) and company-package.lock.json")


# ------------------------------------------------------------- Multica target

class Api:
    def __init__(self, base, token):
        self.base, self.token, self.ws = base.rstrip("/"), token, None

    def __call__(self, method, path, body=None):
        h = {"Content-Type": "application/json", "Authorization": "Bearer " + self.token}
        if self.ws:
            h["X-Workspace-ID"] = self.ws
        req = urllib.request.Request(self.base + path, method=method, headers=h,
                                     data=json.dumps(body).encode() if body is not None else None)
        try:
            with urllib.request.urlopen(req) as r:
                return json.loads(r.read() or b"null")
        except urllib.error.HTTPError as e:
            raise SystemExit(f"{method} {path} -> {e.code} {e.read()[:500].decode()}")

    def list(self, path):
        d = self("GET", path)
        if isinstance(d, dict):
            d = next((v for v in d.values() if isinstance(v, list)), [])
        return d or []


class MulticaDeployer:
    def __init__(self, pkg, api, dry_run, activate_routines=False):
        self.pkg, self.api, self.dry = pkg, api, dry_run
        self.activate = activate_routines
        self.cfg = pkg.target("multica")
        self.changes = 0
        self.ids = {"agent": {}, "squad": {}, "skill": {}, "workflow": {}, "project": {}, "autopilot": {}}

    # -- bookkeeping
    def log(self, op, kind, slug, extra=""):
        if op != "=":
            self.changes += 1
        print(f"{op} {kind:<9} {slug}{('  ' + extra) if extra else ''}")

    def state_path(self):
        return self.pkg.root / ".opc" / f"multica-{self.ws_slug}.json"

    def load_state(self):
        p = self.state_path()
        self.state = json.loads(p.read_text()) if p.exists() else {}

    def save_state(self):
        if self.dry:
            return
        p = self.state_path()
        p.parent.mkdir(exist_ok=True)
        (p.parent / ".gitignore").write_text("*\n")
        p.write_text(json.dumps(self.ids, indent=2) + "\n")

    def match(self, kind, slug, existing, name, name_key="name"):
        """Existing record for slug: by remembered id, else by name."""
        sid = (self.state.get(kind) or {}).get(slug)
        by_id = {x["id"]: x for x in existing}
        if sid in by_id:
            return by_id[sid]
        return next((x for x in existing if x.get(name_key) == name), None)

    def upsert(self, kind, slug, current, desired, create, update, compare=None):
        """Create or update one entity; returns its id (None in a dry run create)."""
        if current is None:
            self.log("+", kind, slug)
            rid = None if self.dry else create(desired)["id"]
        else:
            rid = current["id"]
            diff = [k for k in (compare or desired) if current.get(k) != desired.get(k)]
            self.log("~" if diff else "=", kind, slug, ",".join(diff))
            if diff and not self.dry:
                update(rid, desired)
        self.ids[kind][slug] = rid
        return rid

    # -- steps
    def run(self):
        pkg, api = self.pkg, self.api
        self.ws_slug = self.cfg.get("workspace", pkg.slug)
        ws = next((w for w in api.list("/api/workspaces") if w.get("slug") == self.ws_slug), None)
        if ws is None:
            self.log("+", "workspace", self.ws_slug)
            if self.dry:
                print("(workspace does not exist yet; the rest of the plan assumes an empty workspace)")
                api.ws = None
                self.load_state()
                return self.plan_empty()
            ws = api("POST", "/api/workspaces", {
                "name": pkg.company["name"], "slug": self.ws_slug,
                "description": pkg.company.get("description"),
                "issue_prefix": self.cfg.get("issue_prefix", self.ws_slug[:3].upper())})
        else:
            self.log("=", "workspace", self.ws_slug)
        api.ws = ws["id"]
        self.load_state()
        self.me = api("GET", "/api/me")
        self.me = self.me.get("id") or self.me.get("user", {}).get("id")
        self.skills()
        self.agents()
        self.squads()
        self.statuses()
        self.workflows()
        self.projects()
        self.routines()
        self.save_state()
        print(f"{'plan' if self.dry else 'deploy'}: {self.changes} change(s) in workspace {self.ws_slug}")

    def plan_empty(self):
        for kind, coll in (("skill", self.pkg.skills), ("agent", self.pkg.agents),
                           ("squad", {s: 1 for s in self.pkg.teams if self.pkg.is_squad(s)}),
                           ("workflow", self.pkg.workflows), ("project", self.pkg.projects),
                           ("autopilot", {s: 1 for s, t in self.pkg.tasks.items() if t["meta"].get("recurring")})):
            for slug in coll:
                self.log("+", kind, slug)
        print(f"plan: {self.changes} change(s)")

    def skills(self):
        existing = self.api.list("/api/skills")
        for slug, s in self.pkg.skills.items():
            files = [{"path": str(p.relative_to(s["path"].parent)), "content": p.read_text(encoding="utf-8")}
                     for p in sorted(s["path"].parent.rglob("*"))
                     if p.is_file() and p.name != "SKILL.md" and p.suffix in TEXT_SUFFIXES]
            desired = {"name": slug, "description": s["meta"].get("description", ""), "content": s["raw"]}
            cur = self.match("skill", slug, existing, slug)
            if cur is not None and "content" not in cur:
                cur = self.api("GET", f"/api/skills/{cur['id']}")
            self.upsert("skill", slug, cur, desired,
                        lambda d: self.api("POST", "/api/skills", {**d, "files": files}),
                        lambda i, d: self.api("PUT", f"/api/skills/{i}", {**d, "files": files}))

    def runtime_for(self, slug):
        acfg = (self.cfg.get("agents") or {}).get(slug) or {}
        provider = acfg.get("provider") or (self.cfg.get("defaults") or {}).get("provider", "claude")
        rts = [r for r in self.runtimes if r.get("provider") == provider]
        online = [r for r in rts if r.get("status") == "online"] or rts
        if not online:
            if self.dry:
                return None, acfg
            raise SystemExit(f"agent {slug}: no {provider!r} runtime in this workspace; start the daemon first")
        return online[0]["id"], acfg

    def agents(self):
        self.runtimes = self.api.list("/api/runtimes")
        existing = self.api.list("/api/agents")
        defaults = self.cfg.get("defaults") or {}
        for slug, a in self.pkg.agents.items():
            m = a["meta"]
            runtime_id, acfg = self.runtime_for(slug)
            desired = {
                "name": m["name"],
                "description": m.get("title") or m.get("description", ""),
                "instructions": self.pkg.agent_instructions(slug),
                "model": acfg.get("model", defaults.get("model", "")),
                "runtime_id": runtime_id,
                "max_concurrent_tasks": acfg.get("max_concurrent_tasks", defaults.get("max_concurrent_tasks", 1)),
            }
            cur = self.match("agent", slug, existing, m["name"])
            rid = self.upsert("agent", slug, cur, desired,
                              lambda d: self.api("POST", "/api/agents", {**d, "visibility": "workspace"}),
                              lambda i, d: self.api("PUT", f"/api/agents/{i}", d),
                              compare=["name", "description", "instructions", "model", "runtime_id", "max_concurrent_tasks"])
            want = sorted(self.ids["skill"].get(s) for s in m.get("skills") or [])
            have = sorted(s["id"] for s in (cur or {}).get("skills") or [])
            if want != have:
                self.log("~", "skills", slug, ",".join(m.get("skills") or []) or "(none)")
                if not self.dry and rid:
                    self.api("PUT", f"/api/agents/{rid}/skills", {"skill_ids": want})
            self.secrets(slug, rid)

    def secrets(self, slug, rid):
        env = {}
        for sec in self.pkg.ext.get("secrets") or []:
            if slug not in (sec.get("agents") or []):
                continue
            value = os.environ.get(sec["env"])
            if value:
                env[sec["env"]] = value
            else:
                print(f"! secret    {slug}  {sec['env']} not set in the environment"
                      f"{' (required)' if sec.get('required') else ''}; left unchanged")
        if env:
            self.log("~", "secrets", slug, ",".join(sorted(env)))
            if not self.dry and rid:
                self.api("PUT", f"/api/agents/{rid}/env", {"custom_env": env})

    def squads(self):
        existing = self.api.list("/api/squads")
        for slug, t in self.pkg.teams.items():
            if not self.pkg.is_squad(slug):
                continue
            manager, members = self.pkg.team_members(slug)
            desired = {"name": t["meta"].get("name", slug), "description": t["meta"].get("description", ""),
                       "leader_id": self.ids["agent"].get(manager)}
            cur = self.match("squad", slug, existing, desired["name"])
            rid = self.upsert("squad", slug, cur, desired,
                              lambda d: self.api("POST", "/api/squads", d),
                              lambda i, d: self.api("PUT", f"/api/squads/{i}", d))
            have = {} if (rid is None or cur is None) else {
                m["member_id"]: m for m in self.api.list(f"/api/squads/{rid}/members")}
            for mslug in members:
                aid = self.ids["agent"].get(mslug)
                role = self.pkg.agents[mslug]["meta"].get("title", "")
                if aid is None or aid not in have:
                    self.log("+", "member", f"{slug}/{mslug}")
                    if not self.dry and rid:
                        self.api("POST", f"/api/squads/{rid}/members",
                                 {"member_type": "agent", "member_id": aid, "role": role})
                elif have[aid].get("role") != role:
                    self.log("~", "member", f"{slug}/{mslug}", "role")
                    if not self.dry:
                        self.api("PATCH", f"/api/squads/{rid}/members/role",
                                 {"member_type": "agent", "member_id": aid, "role": role})
            wanted = {self.ids["agent"].get(m) for m in members} | {desired["leader_id"]}
            for aid, mem in have.items():
                if aid not in wanted:
                    self.log("-", "member", f"{slug}/{aid[:8]}")
                    if not self.dry:
                        self.api("DELETE", f"/api/squads/{rid}/members",
                                 {"member_type": mem.get("member_type", "agent"), "member_id": aid})

    def statuses(self):
        have = {s["key"] for s in self.api.list("/api/issue-statuses")}
        for wslug, w in self.pkg.workflows.items():
            for s in w["meta"].get("statuses") or []:
                if s["key"] in have or s["key"] in BUILTIN_STATUSES:
                    continue
                have.add(s["key"])
                self.log("+", "status", s["key"])
                if not self.dry:
                    self.api("POST", "/api/issue-statuses", {
                        "key": s["key"], "name": s["name"], "category": s["category"],
                        "color": s.get("color", "#8b5cf6")})

    def handler(self, h):
        if not h:
            return {"type": "none"}
        if "agent" in h:
            return {"type": "agent", "id": self.ids["agent"].get(h["agent"])}
        if "team" in h:
            t = h["team"]
            if self.pkg.is_squad(t):
                return {"type": "squad", "id": self.ids["squad"].get(t)}
            return {"type": "agent", "id": self.ids["agent"].get(self.pkg.team_members(t)[0])}
        if h.get("role") == "owner" or h.get("member") == "me":
            return {"type": "member", "id": self.me}
        if h.get("role") in ("project_lead", "creator"):
            return {"type": h["role"]}
        raise SystemExit(f"unsupported handler {h!r}")

    @staticmethod
    def rule_text(rules):
        out = []
        if (rules or {}).get("done_requires") == "human":
            out.append("Không tự chuyển issue sang done; chỉ người mới được đóng issue.")
        if (rules or {}).get("max_send_backs"):
            out.append(f"Nếu issue đã bị trả lại {rules['max_send_backs']} lần, dừng lại và hỏi chủ trong comment.")
        return " ".join(out)

    def workflows(self):
        existing = self.api.list("/api/issue-workflows")
        for slug, w in self.pkg.workflows.items():
            m = w["meta"]
            rules = self.rule_text(m.get("rules"))
            steps = []
            for s in m["statuses"]:
                h = self.handler(s.get("handler"))
                instr = (s.get("instructions") or "").strip()
                if rules and h["type"] in ("agent", "squad"):
                    instr = f"{instr}\n{rules}".strip()
                step = {"status_key": s["key"], "handler": h, "instructions": instr,
                        "next_status_key": s.get("next", ""), "back_status_key": s.get("back", "")}
                steps.append(step)
            desired = {"name": m.get("name", slug), "description": (m.get("description") or "")[:256], "steps": steps}
            cur = self.match("workflow", slug, existing, desired["name"])
            if cur is not None:
                cur = dict(cur)
                cur["steps"] = self.normalize_steps(cur.get("steps") or [], {s["status_key"] for s in steps})
            self.upsert("workflow", slug, cur, desired,
                        lambda d: self.api("POST", "/api/issue-workflows", d),
                        lambda i, d: self.api("PATCH", f"/api/issue-workflows/{i}", d))

    @staticmethod
    def normalize_steps(steps, wanted_keys):
        """Server steps in the request shape; drops fixed statuses Multica adds itself."""
        out = []
        for s in steps:
            if s["status_key"] in ("cancelled",) and s["status_key"] not in wanted_keys:
                continue
            h = s.get("handler") or {"type": "none"}
            out.append({"status_key": s["status_key"],
                        "handler": {k: v for k, v in h.items() if k in ("type", "id") and v},
                        "instructions": s.get("instructions") or "",
                        "next_status_key": s.get("next_status_key") or "",
                        "back_status_key": s.get("back_status_key") or ""})
        return out

    def projects(self):
        existing = self.api.list("/api/projects")
        bindings = self.pkg.ext.get("projects") or {}
        for slug, p in self.pkg.projects.items():
            m = p["meta"]
            owner = m.get("owner")
            desired = {"title": m.get("name", slug), "description": m.get("description") or p["body"].strip()[:2000]}
            if owner:
                desired.update(lead_type="agent", lead_id=self.ids["agent"].get(owner))
            cur = self.match("project", slug, existing, desired["title"], name_key="title")
            rid = self.upsert("project", slug, cur, desired,
                              lambda d: self.api("POST", "/api/projects", d),
                              lambda i, d: self.api("PUT", f"/api/projects/{i}", d))
            wf = (bindings.get(slug) or {}).get("workflow")
            if wf:
                wid = self.ids["workflow"].get(wf)
                if cur is None or cur.get("workflow_id") != wid or wid is None:
                    self.log("~", "binding", f"{slug} -> {wf}")
                    if not self.dry and rid:
                        self.api("POST", f"/api/projects/{rid}/workflow", {"workflow_id": wid})

    def routines(self):
        existing = self.api.list("/api/autopilots")
        rcfg = self.pkg.ext.get("routines") or {}
        for slug, t in self.pkg.tasks.items():
            m = t["meta"]
            if not m.get("recurring"):
                continue
            who = m.get("assignee")
            if who in self.pkg.teams and self.pkg.is_squad(who):
                atype, aid = "squad", self.ids["squad"].get(who)
            else:
                aslug = self.pkg.team_members(who)[0] if who in self.pkg.teams else who
                atype, aid = "agent", self.ids["agent"].get(aslug)
            desired = {"title": m.get("name", slug), "description": t["body"].strip(),
                       "project_id": self.ids["project"].get(m.get("project")),
                       "assignee_type": atype, "assignee_id": aid, "execution_mode": "create_issue"}
            cur = self.match("autopilot", slug, existing, desired["title"], name_key="title")
            rid = self.upsert("autopilot", slug, cur, desired,
                              lambda d: self.api("POST", "/api/autopilots", d),
                              lambda i, d: self.api("PATCH", f"/api/autopilots/{i}", d),
                              compare=["title", "description", "project_id", "assignee_type", "assignee_id"])
            if cur is None and not self.dry and rid and not self.activate:
                self.api("PATCH", f"/api/autopilots/{rid}", {"status": "paused"})
                print(f"  autopilot {slug} created paused; enable it in Multica or deploy with --activate-routines")
            have = [] if cur is None or rid is None else (self.api("GET", f"/api/autopilots/{rid}").get("triggers") or [])
            for trig in (rcfg.get(slug) or {}).get("triggers") or []:
                cron, tz = trig.get("cron"), trig.get("timezone", "Asia/Ho_Chi_Minh")
                if any(h.get("cron_expression") == cron for h in have):
                    continue
                self.log("+", "trigger", f"{slug} {cron} {tz}")
                if not self.dry and rid:
                    self.api("POST", f"/api/autopilots/{rid}/triggers",
                             {"kind": "schedule", "cron_expression": cron, "timezone": tz})


def multica_api():
    home = Path(os.path.expanduser(os.environ.get("MULTICA_HOME", "~/multica-spike")))
    token_file = Path(os.environ.get("MULTICA_TOKEN_FILE", home / ".pat"))
    if not token_file.exists():
        raise SystemExit(f"{token_file}: no token; run multica/stack/bootstrap.py first")
    return Api(os.environ.get("MULTICA_API", "http://127.0.0.1:8310"), token_file.read_text().strip())


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    sub = ap.add_subparsers(dest="cmd", required=True)
    for name in ("lint", "pack", "plan", "deploy"):
        s = sub.add_parser(name)
        s.add_argument("package")
        if name == "pack":
            s.add_argument("-o", "--out")
        if name in ("plan", "deploy"):
            s.add_argument("--target", default="multica", choices=["multica"])
        if name == "deploy":
            s.add_argument("--activate-routines", action="store_true")
    a = ap.parse_args()
    pkg = Package(a.package)
    ok = print_lint(pkg)
    if a.cmd == "lint":
        sys.exit(0 if ok else 1)
    if not ok:
        sys.exit("lint failed; fix the errors first")
    if a.cmd == "pack":
        return pack(pkg, a.out)
    MulticaDeployer(pkg, multica_api(), dry_run=a.cmd == "plan",
                    activate_routines=getattr(a, "activate_routines", False)).run()


if __name__ == "__main__":
    main()

