content.content:
# fgopc extension: what Agent Companies v1 has no place for. Tools that do not
# know it ignore it (Agent Companies §15).
schema: fgopc/v1

projects:                 # project -> workflow (columns)
  product-app:       { workflow: feature }
  content-marketing: { workflow: content }
  marketing-analytics: {}  # reports and audits, no workflow: the agent moves its issue to in_review

secrets:                  # declared only; values come from the environment at deploy time
  - { id: github, env: GH_TOKEN, agents: [minh, quan], required: false, label: "GitHub token để đẩy nhánh và đọc PR" }
  - { id: ga4-property, env: GA4_PROPERTY_ID, agents: [analytics-reporter, tracking-specialist, seo-specialist], required: false, label: "ID property GA4, vd 123456789" }
  - { id: gsc-site, env: GSC_SITE_URL, agents: [analytics-reporter, seo-specialist], required: false, label: "Site Search Console, vd sc-domain:example.com" }

mcp:                      # MCP servers: `opc.mjs tools` installs the pinned package on the
                          # daemon host; deploy creates the workspace server and gives it to
                          # the listed agents. ${VAR} is filled from the deploy environment.
  google-analytics:       # Google's official GA4 MCP (read-only Admin + Data API)
    install: { pypi: analytics-mcp, version: 0.7.0, python: "3.12" }
    command: analytics-mcp
    env:
      GOOGLE_APPLICATION_CREDENTIALS: ${GOOGLE_APPLICATION_CREDENTIALS}
      GOOGLE_CLOUD_PROJECT: ${GOOGLE_CLOUD_PROJECT:-}  # optional quota project
    agents: [analytics-reporter, tracking-specialist, seo-specialist]
  search-console:         # Search Console: search analytics, URL inspection, sitemaps
    install: { npm: mcp-server-gsc, version: 0.3.0 }
    command: mcp-server-gsc
    env:
      GOOGLE_APPLICATION_CREDENTIALS: ${GOOGLE_APPLICATION_CREDENTIALS}
    agents: [analytics-reporter, seo-specialist]

routines:                 # schedules for recurring TASK.md
  weekly-content-plan:
    triggers:
      - { cron: "0 9 * * 1", timezone: Asia/Ho_Chi_Minh }
  weekly-analytics-report:  # one hour before the content plan, which reads it
    triggers:
      - { cron: "0 8 * * 1", timezone: Asia/Ho_Chi_Minh }

targets:
  multica:
    workspace: opc-studio
    issue_prefix: STU
    # Business agents never go to the System Operator's fg-server-ops daemon.
    # Switch to fg-server-opc once opc-multica-daemon (stack/agent-user.sh) runs.
    defaults: { provider: claude, model: haiku, max_concurrent_tasks: 1, runtime: fg-server-opc }
    agents:
      minh: { model: sonnet }

